// ManageCorrectAnswerPage.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

/* ============================================================
   ⭐ PRISMJS
============================================================ */
import Prism from "prismjs";
import "prismjs/themes/prism-okaidia.css";
import "prismjs/components/prism-clike";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-python";
import "prismjs/components/prism-markup";
import "prismjs/components/prism-json";
import "prismjs/components/prism-markdown";

/* ============================================================
   PARTICLES
============================================================ */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);
    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ============================================================
   Utils
============================================================ */
const formatStudyType = (type) =>
    type
        .toLowerCase()
        .split("_")
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(" ");

/* ============================================================
   PAGE
============================================================ */
export default function ManageCorrectAnswerPage() {
    const { taskId } = useParams();
    const navigate = useNavigate();

    const [task, setTask] = useState(null);
    const [loading, setLoading] = useState(true);

    const [toast, setToast] = useState(null);
    const showToast = (msg, type = "success") => {
        setToast({ msg, type });
        setTimeout(() => {
            setToast(null);
        }, 1500);
    };

    /* ============================================================
       FORM STATE
    ============================================================ */
    const [form, setForm] = useState({});

    const updateField = (key, val) => {
        setForm((prev) => ({ ...prev, [key]: val }));
    };

    /* ============================================================
       Toggle Helpers (AddTaskPage ile aynı)
============================================================ */
    const toggleMultiChoice = (key) => {
        setForm((prev) => ({
            ...prev,
            [key]: !prev[key],
        }));
    };

    const toggleSingleChoice = (groupKeys, key) => {
        setForm((prev) => {
            const updated = { ...prev };
            const isAlready = prev[key];

            groupKeys.forEach((k) => (updated[k] = false));
            if (!isAlready) updated[key] = true;

            return updated;
        });
    };

    const countSelected = (keys) =>
        keys.reduce((acc, k) => acc + (form[k] ? 1 : 0), 0);

    /* ============================================================
       LOAD TASK
============================================================ */
    useEffect(() => {
        const load = async () => {
            try {
                const r = await fetch(`http://localhost:8080/api/tasks/details/${taskId}`);
                const data = await r.json();
                setTask(data);

                let initial = {};
                if (data.studyType === "BUG_CATEGORIZATION" && data.bugCorrectAnswer)
                    initial = { ...data.bugCorrectAnswer };
                if (data.studyType === "CODE_CLONE" && data.cloneCorrectAnswer)
                    initial = { ...data.cloneCorrectAnswer };
                if (data.studyType === "SNAPSHOT_TESTING" && data.snapshotCorrectAnswer)
                    initial = { ...data.snapshotCorrectAnswer };
                if (data.studyType === "SOLID_DETECTION" && data.solidCorrectAnswer)
                    initial = { ...data.solidCorrectAnswer };

                delete initial.id;
                setForm(initial);
            } catch (e) {
                showToast("Failed to load task", "error");
            } finally {
                setLoading(false);
            }
        };

        load();
    }, [taskId]);

    /* ============================================================
       SAVE
============================================================ */
    const handleSave = async () => {
        const type = task.studyType;

        // ⭐ VALIDATION
        if (type === "BUG_CATEGORIZATION") {
            const keys = [
                "configurationIssue",
                "networkIssue",
                "databaseIssue",
                "guiIssue",
                "performanceIssue",
                "permissionIssue",
                "securityIssue",
                "functionalIssue",
                "testCodeIssue",
            ];
            if (countSelected(keys) < 1)
                return showToast("Select at least one bug category", "error");
        }

        if (type === "CODE_CLONE") {
            const keys = ["type1", "type2", "type3", "type4", "notClone"];
            if (countSelected(keys) !== 1)
                return showToast("Select exactly one clone type", "error");
        }

        if (type === "SNAPSHOT_TESTING") {
            const keys = [
                "colorChange",
                "shapeChange",
                "positionChange",
                "layoutChange",
                "visibilityChange",
                "fontChange",
                "contentChange",
                "sizeChange",
                "unknownChange",
            ];
            if (countSelected(keys) < 1)
                return showToast("Select at least one UI change", "error");
        }

        if (type === "SOLID_DETECTION") {
            const difficultyKeys = ["easy", "medium", "hard"];
            const principleKeys = ["srp", "ocp", "lsp", "isp", "dip"];

            if (countSelected(difficultyKeys) !== 1)
                return showToast("Select exactly one difficulty", "error");

            if (countSelected(principleKeys) < 1)
                return showToast("Select at least one violated principle", "error");
        }

        // ⭐ SAVE
        try {
            const r = await fetch(
                `http://localhost:8080/api/tasks/update-correct-answer/${taskId}`,
                {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(form),
                }
            );

            if (!r.ok) throw new Error();

            showToast("Correct answer saved!", "success");

            // ✔ 1 saniye sonra geri dön
            setTimeout(() => navigate(-1), 1000);

        } catch (e) {
            showToast("Failed to save", "error");
        }
    };

    if (loading) return <div style={{ color: "#fff", textAlign: "center", marginTop: 50 }}>Loading...</div>;
    if (!task) return <div style={{ color: "red" }}>Task not found</div>;

    const type = task.studyType;

    /* ============================================================
       CHIP STYLE — renderBooleanField
============================================================ */
    const renderBooleanField = (key, label, color = "#60a5fa", handler = null) => {
        const active = !!form[key];

        return (
            <div
                key={key}
                onClick={() => {
                    if (handler) handler();
                    else toggleMultiChoice(key);
                }}
                style={{
                    ...styles.answerChip,
                    ...(active ? styles.answerChipActive : {}),
                }}
            >
                {label}
            </div>
        );
    };

    /* ============================================================
       FORM RENDERING
============================================================ */
    const renderForm = () => {
        switch (type) {
            case "BUG_CATEGORIZATION":
                return (
                    <div style={styles.answerRow}>
                        {renderBooleanField("functionalIssue", "FUNCTIONAL ISSUE")}
                        {renderBooleanField("securityIssue", "SECURITY ISSUE")}
                        {renderBooleanField("guiIssue", "GUI ISSUE")}
                        {renderBooleanField("performanceIssue", "PERFORMANCE")}
                        {renderBooleanField("configurationIssue", "CONFIGURATION")}
                        {renderBooleanField("networkIssue", "NETWORK")}
                        {renderBooleanField("databaseIssue", "DATABASE")}
                        {renderBooleanField("permissionIssue", "PERMISSION")}
                        {renderBooleanField("testCodeIssue", "TEST CODE")}
                    </div>
                );

            case "CODE_CLONE": {
                const keys = ["type1", "type2", "type3", "type4", "notClone"];  // ⭐ updated
                return (
                    <div style={styles.answerRow}>
                        {renderBooleanField("type1", "TYPE-1", "#60a5fa", () =>
                            toggleSingleChoice(keys, "type1")
                        )}
                        {renderBooleanField("type2", "TYPE-2", "#60a5fa", () =>
                            toggleSingleChoice(keys, "type2")
                        )}
                        {renderBooleanField("type3", "TYPE-3", "#60a5fa", () =>
                            toggleSingleChoice(keys, "type3")
                        )}
                        {renderBooleanField("type4", "TYPE-4", "#60a5fa", () =>
                            toggleSingleChoice(keys, "type4")
                        )}
                        {renderBooleanField("notClone", "NOT A CLONE", "#60a5fa", () =>
                            toggleSingleChoice(keys, "notClone")
                        )}
                    </div>
                );
            }
            case "SNAPSHOT_TESTING":
                return (
                    <div style={styles.answerRow}>
                        {[
                            "colorChange",
                            "shapeChange",
                            "positionChange",
                            "layoutChange",
                            "visibilityChange",
                            "fontChange",
                            "contentChange",
                            "sizeChange",
                            "unknownChange",
                        ].map((k) => renderBooleanField(k, k.replace(/([A-Z])/g, " $1")))}
                    </div>
                );

            case "SOLID_DETECTION": {
                const diffKeys = ["easy", "medium", "hard"];

                return (
                    <>
                        <h4 style={styles.subTitle}>Violated Principles</h4>
                        <div style={styles.answerRow}>
                            {["srp", "ocp", "lsp", "isp", "dip"].map((k) =>
                                renderBooleanField(k, k.toUpperCase())
                            )}
                        </div>

                        <h4 style={{ ...styles.subTitle, marginTop: 18 }}>Difficulty</h4>
                        <div style={styles.answerRow}>
                            {diffKeys.map((k) =>
                                renderBooleanField(k, k.toUpperCase(), "#facc15", () =>
                                    toggleSingleChoice(diffKeys, k)
                                )
                            )}
                        </div>
                    </>
                );
            }

            default:
                return <p>No form for this type.</p>;
        }
    };

    /* ============================================================
       RENDER
============================================================ */
    return (
        <div style={styles.container}>
            <FloatingParticles />

            {toast && (
                <div
                    style={{
                        ...styles.toast,
                        ...(toast.type === "success"
                            ? styles.toastSuccess
                            : styles.toastError),
                    }}
                >
                    {toast.msg}
                </div>
            )}

            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Manage Correct Answer</h2>
                <button
                    style={styles.backButton}
                    onClick={() => navigate(-1)}
                >
                    ← Back
                </button>
            </div>

            <div style={styles.content}>
                <div style={styles.mainCard}>
                    <div style={styles.typeRow}>
                        <label style={styles.labelInline}>Study Type</label>
                        <div style={styles.typePill}>{formatStudyType(type)}</div>
                    </div>


                    <div style={{ marginTop: 20 }}>{renderForm()}</div>

                    <button
                        style={styles.saveButton}
                        className="save-btn"
                        onClick={handleSave}
                    >
                        💾 Save Correct Answer
                    </button>
                </div>
            </div>

            <style>
                {`
                    @keyframes floatParticle {
                        0% { transform: translateY(0); opacity:.4; }
                        50% { opacity: 1; }
                        100% { transform: translateY(-120vh); opacity: 0;}
                    }
                `}
            </style>
        </div>
    );
}

